package pe.nexo.store.config;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import pe.nexo.store.auth.TokenService;import java.io.IOException;import java.util.List;
@Component public class JwtAuthFilter extends OncePerRequestFilter { private final TokenService tokens; public JwtAuthFilter(TokenService tokens){this.tokens=tokens;} @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")&&tokens.valid(h.substring(7)))SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("admin",null,List.of(new SimpleGrantedAuthority("ROLE_ADMIN"))));chain.doFilter(req,res);}}
